// Transforme le rapport JSON de l'API en texte lisible + prompt pour le LLM.
const r = $input.first().json;
const lot = (l) => `- ${l.medicament}, lot ${l.numero_lot} : ${l.quantite} unité(s), expiration le ${l.date_expiration} (` +
  (l.jours_restants < 0 ? `expiré depuis ${-l.jours_restants} jour(s)` : `${l.jours_restants} jour(s) restants`) + ')';
const stock = (s) => `- ${s.medicament} : ${s.stock_utilisable} unité(s) utilisable(s), seuil d'alerte ${s.seuil_alerte}`;
const section = (titre, liste, f) => `${titre} (${liste.length}) :\n` + (liste.length ? liste.map(f).join('\n') : '- aucun');

const faits = [
  `Date du rapport : ${r.date}`,
  `Médicaments au catalogue : ${r.total_medicaments}`,
  section('LOTS EXPIRÉS À RETIRER DU STOCK', r.lots_expires, lot),
  section('LOTS QUI EXPIRENT DANS 30 JOURS OU MOINS', r.lots_sous_30j, lot),
  section('MÉDICAMENTS EN RUPTURE', r.ruptures, stock),
  section('MÉDICAMENTS EN STOCK BAS', r.stock_bas, stock),
  section('LOTS QUI EXPIRENT ENTRE 31 ET 90 JOURS', r.lots_sous_90j, lot),
].join('\n\n');

const prompt = `Tu es l'assistant de gestion du stock de médicaments du Centre de Santé Cherrat.
Rédige en français la liste des actions du jour pour le Docteur et le Major, à partir des FAITS ci-dessous.

Règles :
- Utilise UNIQUEMENT les faits fournis. N'invente aucun médicament, aucune quantité, aucune date.
- Écris uniquement une liste à puces d'actions (une ligne par action, commençant par "- "), de la plus urgente à la moins urgente :
  1) retirer les lots expirés, 2) utiliser en premier les lots qui expirent sous 30 jours, 3) commander les médicaments en rupture, 4) commander les médicaments en stock bas.
- Chaque ligne cite le médicament, le numéro de lot s'il existe et la quantité, recopiés exactement depuis les faits.
- Ne mentionne pas les catégories vides. Pas d'introduction ni de conclusion.
- Aucun conseil médical, de prescription ou de posologie.
- 120 mots maximum, texte simple, sans tableau ni mise en forme Markdown (pas de ** ni de #).

FAITS :
${faits}`;

// La synthèse chiffrée est écrite par le code, pas par le LLM (il se trompe en calcul).
const synthese = r.nb_alertes === 0
  ? "Aucune alerte aujourd'hui."
  : `${r.nb_alertes} alerte(s) à traiter aujourd'hui : ${r.lots_expires.length} lot(s) expiré(s), ` +
    `${r.lots_sous_30j.length} lot(s) expirant sous 30 jours, ${r.ruptures.length} rupture(s), ${r.stock_bas.length} stock(s) bas.`;

return [{ json: { ...r, faits, prompt, synthese } }];

// Met en page la réponse du LLM + les données brutes vérifiables (contrôle humain).
const d = $('Préparer le prompt').first().json;
const cfg = $('Configuration').first().json;
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const texte = String($input.first().json.response || '').replace(/\*\*/g, '').trim();
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#1e293b">
<h2 style="color:#115e59">Stock Cherrat — rapport du ${d.date}</h2>
<p><b>${esc(d.synthese)}</b></p>
<p>Actions prioritaires :</p>
<p>${esc(texte).replace(/\n+/g, '<br>')}</p>
<p style="font-size:12px;color:#64748b">Liste d'actions rédigée par l'IA locale (${esc(cfg.LLM_MODEL)}). Vérifiez-la avec les données ci-dessous avant toute décision.</p>
<h3>Données calculées par l'application</h3>
<pre style="background:#f1f5f9;padding:12px;border-radius:6px;font-size:12px;white-space:pre-wrap;word-break:break-word">${esc(d.faits)}</pre>
</div>`;
return [{ json: { sujet: `Stock Cherrat : ${d.nb_alertes} alerte(s) — ${d.date}`, html, source: 'ia' } }];

// Repli sans IA : si Ollama ne répond pas, on envoie quand même les données brutes.
const d = $('Préparer le prompt').first().json;
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#1e293b">
<h2 style="color:#115e59">Stock Cherrat — rapport du ${d.date}</h2>
<p><b>${esc(d.synthese)}</b></p>
<p style="color:#b45309">L'assistant IA (Ollama) n'a pas répondu : voici les données brutes du stock.</p>
<pre style="background:#f1f5f9;padding:12px;border-radius:6px;font-size:12px;white-space:pre-wrap;word-break:break-word">${esc(d.faits)}</pre>
</div>`;
return [{ json: { sujet: `Stock Cherrat : ${d.nb_alertes} alerte(s) — ${d.date} (sans IA)`, html, source: 'repli' } }];
